def on_post_created(post):
    author = post.author_id
    recent_posts(author).lpush(post.id); recent_posts(author).ltrim(0, 99)
    if follower_count(author) > 10_000:
        return                      # celebrity: pulled at read time
    for page in followers(author, page_size=1000):
        active = [f for f in page if last_seen(f) < 30*DAY]
        with redis.pipeline() as p:
            for f in active:
                p.zadd(f"timeline:{f}", {post.id: post.id})
                p.zremrangebyrank(f"timeline:{f}", 0, -501)
            p.execute()

def next_id(shard_id):
    now = current_millis() - EPOCH
    if now == last_ms[shard_id]:
        seq[shard_id] = (seq[shard_id] + 1) & 0x3FF
        if seq[shard_id] == 0: now = wait_next_ms(now)
    else:
        seq[shard_id] = 0
    last_ms[shard_id] = now
    return (now << 23) | (shard_id << 10) | seq[shard_id]

def on_object_created(evt):
    m = db.get_media(evt.media_id)
    if m.status in ("READY", "BLOCKED", "DELETED"): return  # already done
    raw = store.get(evt.key)
    if sha256(raw) != m.sha256: return mark_failed(m)
    if phash_blocklist.match(phash(raw)): return mark_blocked(m)
    img = strip_exif(decode(raw))
    keys = {}
    for w in (150, 320, 640, 1080):
        k = f"derived/{m.content_hash}_{w}.avif"
        store.put(k, encode_avif(resize(img, w)))
        keys[w] = k
    db.update("UPDATE media SET status='READY', variants=%s WHERE id=%s AND status='PENDING'", keys, m.id)
